  window.BIOCS_REGULATION_BRIDGE_CHAPTERS=chapters.map(({id,title,courseCode})=>({id,title,course:courseCode,origin:'Original regulation bridge · synthetic arithmetic · source-checked'}));
  for(const chapter of chapters){
    const course=window.BIOCS_BOOK.find(c=>c.code===chapter.courseCode);
    if(!course)throw new Error(`Regulation bridge course missing: ${chapter.courseCode}`);
    if(window.BIOCS_BOOK.some(c=>c.chapters.some(item=>item.id===chapter.id)))throw new Error(`Duplicate regulation chapter: ${chapter.id}`);
    window.BIOCS_INTUITION[chapter.id]=chapter.intuition;
    window.BIOCS_DATA_LENS[chapter.id]=chapter.lens;
    delete chapter.lens;
    delete chapter.courseCode;
    chapter.intro='';
    chapter.more=[...new Set(chapter.sections.flatMap(section=>section[2]))];
    course.chapters.push(chapter);
  }
